head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");

//#include("../js/controlResize.js"); // 화면 리사이징
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
scwin.vScrenID = "ULDINS16100.xml";
scwin.nPreRow = -1;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/**
 *  화면 초기화
 */
scwin.fn_Init = function() {
    $c.cm.PanelToGroupBox(panel_1);
    $c.cm.PanelToGroupBox(panel_2);
    //PanelToGroupBox(panel_4);
    //PanelToGroupBox(panel_5);

    // 콤보 세팅.
    scwin.fn_SetCombo();

    // 기본값 세팅
    scwin.fn_SetDefaultVal();
};


/**
 *  콤보박스 만들기
 */
scwin.fn_SetCombo = function() {
    ins_combo_set(dts_CurrTpCd, scwin.vScrenID, SCREN_PROCS_TP_CD_01, "02475"); // 발행통화
    ins_combo_set(dts_STD_CD_APCT_TP_CD, scwin.vScrenID, SCREN_PROCS_TP_CD_01, "03527"); //03527 - 신청자구분 

};

/**
 *  화면의 기본값 세팅
 */
scwin.fn_SetDefaultVal = function() {
    txb_SRCH_STD_CD.setValue("KRE");
    $c.stf.showObj(txb_SRCH_ISUR_NM, false);
};


/**
 *  데이터셋 초기화.
 */
scwin.fn_InitDs = function(pFg) {
    dts_ApplInfo.removeAll();
};


/**
 * CD접수정보 조회(CD접수마스터 조회)
 */
scwin.ins_Search = function() {
    //데이터셋 초기화
    scwin.fn_InitDs();

    // 조회조건 체크.
    if (!scwin.fn_ChkValid("select")) {
        return;
    }

    // 조회 버튼 클릭 후 바로 버튼 클릭 안되게 처리 20220922
    fn_SetDisableSelectBtn(btn_search, true);

    // Lodaing~~~ 표시
    $c.cm.ShowWin(grd_ApplInfo);
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamic" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.rcpt.select.listStdCdCdInfoInquiry" + "&outputMessageId=INS_LIST_STDCD_CD_INFO_INQUIRY" + "&param01=" + $c.stf.getObjectValue(txb_SRCH_STD_CD) + "&param02=" + $c.stf.getObjectValue(txb_SRCH_STD_NM) + "&param03=" + $c.stf.getObjectValue(txb_SRCH_ISUR_CD) + "&param04=" + $c.stf.getObjectValue(edt_FROM_ISU_DD) + "&param05=" + $c.stf.getObjectValue(edt_TO_ISU_DD) + "&param06=" + $c.stf.getObjectValue(edt_FROM_STD_CD_GRNT_DD) + "&param07=" + $c.stf.getObjectValue(edt_TO_STD_CD_GRNT_DD);
    dts_ApplInfo.DataID = encodeURI(url);
    dts_ApplInfo.Reset();
};


/**
 * 표준코드등록
 */
scwin.ins_modify = function() {
    trs_Save.Action = "/StdCdCdInfoAction.do?method=modifyStdCdCdInfo" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03 + "&queryId=lds.ins.stdcd.update.modifyStdCdCdInfo";
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_ApplInfo)";
    trs_Save.Parameters = "EMP_NO=" + js_emp_no + ",EMP_NM=" + js_emp_nm + ",EMAIL=" + js_email;
    trs_Save.Post();
};


/**
 * 표준코드 삭제 사전작업
 */
scwin.ins_Delete = function() {
    // 사전체크
    if (!scwin.fn_ChkValid("delete")) {
        // 삭제요청건이 있는 경우 ULDINS11000 화면에서 삭제함.
        fn_alertRequiredDelByWeb();
        return;
    }

    // 사전체크
    if (!fn_alertDelConfirm()) {
        return;
    }

    // 삭제사유 세팅 팝업
    ins_popupOpen(txb_DEL_RSN, "", "ULDINS91500", "삭제사유", "470", "170");
};


/**
 * 표준코드 삭제
 */
scwin.ins_remove = function() {

    //dts_Delete.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
    dts_Delete.insertRow();
    var nRow = dts_ApplInfo.getRowPosition();
    dts_Delete.setCellData(1, "STD_CD", dts_ApplInfo.getCellData(nRow, "STD_CD"));
    dts_Delete.setCellData(1, "ISU_NM", dts_ApplInfo.getCellData(nRow, "ISU_NM"));
    dts_Delete.setCellData(1, "CHG_RSN", txb_DEL_RSN.getValue());
    trs_Delete.Action = "/StdCdCdInfoAction.do?method=removeStdCdCdInfo" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04 + "&queryId=lds.ins.stdcd.delete.removeStdCdCdInfo";
    trs_Delete.KeyName = "toinb_dataid4";
    trs_Delete.KeyValue = "JSP(I:pInput=dts_Delete)";
    trs_Delete.Parameters = "EMP_NO=" + js_emp_no + ",EMP_NM=" + js_emp_nm + ",EMAIL=" + js_email;
    trs_Delete.Post();
};


/**
 * 사전체크
 */
scwin.fn_ChkValid = function(pGubun) {
    if (pGubun == undefined) {
        return true;
    }
    if (pGubun == "select") {
        if ($c.stf.compareFromToDate2(edt_FROM_ISU_DD, edt_TO_ISU_DD) == false) {
            return false;
        }
        if ($c.stf.compareFromToDate2(edt_FROM_STD_CD_GRNT_DD, edt_TO_STD_CD_GRNT_DD) == false) {
            return false;
        }
    } else if (pGubun == "save") {
        if (!$c.cp.isModified(dts_ApplInfo)) {
            $c.win.alert("변경된 데이터가 없습니다.");
            return false;
        }
        if (txb_ISU_NM.getValue() == "" || txb_ISU_NM.getValue().indexOf(" ") == "") {
            $c.win.alert($c.stf.getMessageParam("MSG-A005", "한글종목명"));
            txb_ISU_NM.focus();
            return false;
        }
        if (txb_ISU_ABBRV.getValue() == "" || txb_ISU_ABBRV.getValue().indexOf(" ") == "") {
            $c.win.alert($c.stf.getMessageParam("MSG-A005", "한글종목약명"));
            txb_ISU_ABBRV.focus();
            return false;
        }
        if (txb_ISU_ENG_NM.getValue() == "" || txb_ISU_ENG_NM.getValue().indexOf(" ") == "") {
            $c.win.alert($c.stf.getMessageParam("MSG-A005", "영문종목명"));
            txb_ISU_ENG_NM.focus();
            return false;
        }
        if (txb_ISU_ENG_ABBRV.getValue() == "" || txb_ISU_ENG_ABBRV.getValue().indexOf(" ") == "") {
            $c.win.alert($c.stf.getMessageParam("MSG-A005", "영문종목약명"));
            txb_ISU_ENG_ABBRV.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(txb_ISU_NM, 80, "한글종목명")) {
            txb_ISU_NM.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(txb_ISU_ABBRV, 40, "한글종목약명")) {
            txb_ISU_ABBRV.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(txb_ISU_ENG_NM, 80, "영문종목명")) {
            txb_ISU_ENG_NM.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(txb_ISU_ENG_ABBRV, 40, "영문종목약명")) {
            txb_ISU_ENG_ABBRV.focus();
            return false;
        }
        if ($c.stf.getObjectValue(txb_ISUR_CD) == "") {
            $c.win.alert("발행기관 코드를 확인하세요.");
            txb_ISUR_CD.focus();
            return false;
        }
        if ($c.stf.getObjectValue(txb_ISU_NM) == "") {
            $c.win.alert("기준명을 확인하세요.");
            txb_ISU_NM.focus();
            return false;
        }
        if ($c.stf.getObjectValue(txb_UNQ_ISU_NM) == "") {
            $c.win.alert("고유명을 확인하세요.");
            txb_UNQ_ISU_NM.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(txb_UNQ_ISU_NM, 20, "한글고유명")) {
            //txb_UNQ_ISU_NM.value = "";
            txb_UNQ_ISU_NM.focus();
            return false;
        }
        if ($c.stf.getObjectValue(txb_UNQ_ISU_ENG_NM) == "") {
            $c.win.alert("고유명(영문)을 확인하세요.");
            txb_UNQ_ISU_ENG_NM.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(txb_UNQ_ISU_ENG_NM, 20, "영문고유명")) {
            //txb_UNQ_ISU_ENG_NM.value = "";
            txb_UNQ_ISU_ENG_NM.focus();
            return false;
        }
        if ($c.stf.getObjectValue(edt_ISU_DD) == "") {
            $c.win.alert("발행일을 확인하세요.");
            edt_ISU_DD.focus();
            return false;
        }
        if ($c.stf.getObjectValue(edt_EXP_DD) == "") {
            $c.win.alert("상환일(만기일)을 확인하세요.");
            edt_EXP_DD.focus();
            return false;
        }
        if (fn_CheckDateObj(edt_ISU_DD, "발행일")) return false;
        if (fn_CheckDateObj(edt_EXP_DD, "상환일(만기일)")) return false;
        if ($c.stf.getObjectValue(edt_YY1_BAS_YD) == "") {
            $c.win.alert("연수익률을 확인하세요.");
            edt_YY1_BAS_YD.focus();
            return false;
        }
        if ($c.stf.getObjectValue(edt_DC_SALES) == "") {
            $c.win.alert("할인매출액을 확인하세요.");
            edt_DC_SALES.focus();
            return false;
        }
        if ($c.stf.getObjectValue(edt_DC_RT) == "") {
            $c.win.alert("할인율을 확인하세요.");
            edt_DC_RT.focus();
            return false;
        }
        if ($c.stf.getObjectValue(cmb_CURR_TP_CD) == "") {
            $c.win.alert("발행통화를 확인하세요.");
            cmb_CURR_TP_CD.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(txb_BRN_NM, 80, "지점명")) {
            txb_BRN_NM.focus();
            return false;
        }

        //CFI체크
        if ($c.stf.getObjectValue(cmb_cb_p_group) == "") {
            $c.win.alert($c.stf.getMessageParam("MSG-A005", "CFI_그룹"));
            cmb_cb_p_group.focus();
            return false;
        }
        if ($c.stf.getObjectValue(cmb_cb_p_attr_1) == "") {
            $c.win.alert($c.stf.getMessageParam("MSG-A005", "CFI_1차속성"));
            cmb_cb_p_attr_1.focus();
            return false;
        }
        if ($c.stf.getObjectValue(cmb_cb_p_attr_2) == "") {
            $c.win.alert($c.stf.getMessageParam("MSG-A005", "CFI_2차속성"));
            cmb_cb_p_attr_2.focus();
            return false;
        }
        if ($c.stf.getObjectValue(cmb_cb_p_attr_3) == "") {
            $c.win.alert($c.stf.getMessageParam("MSG-A005", "CFI_3차속성"));
            cmb_cb_p_attr_3.focus();
            return false;
        }
        if ($c.stf.getObjectValue(cmb_cb_p_attr_4) == "") {
            $c.win.alert($c.stf.getMessageParam("MSG-A005", "CFI_4차속성"));
            cmb_cb_p_attr_4.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(txa_NUSUAL_ISU_COND_CONTN, 60, "특이발행조건")) {
            //txb_ISU_ENG_ABBRV.value = "";
            txa_NUSUAL_ISU_COND_CONTN.focus();
            return false;
        }
    } else if (pGubun == "delete") {
        //삭제 요청건이 존재하는지 체크
        var nRow = dts_ApplInfo.getRowPosition();
        var nDelCnt = dts_ApplInfo.getCellData(nRow, "DEL_CNT");
        if (eval(nDelCnt) > 0) {
            // 삭제요청건 존재
            return false;
        }
    }
    return true;
};


/**
 * 발생기관 팝업에서 값 받음.
 */
scwin.fn_GetParam = function(arrPar) {
    arrPar[0] = txb_param1.getValue(); // 표준코드 OR 발행기관 코드      
    arrPar[1] = txb_param2.getValue();
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};


/**
 * 첨부파일
 */
scwin.ins_ReadStdCdCdInfoFile = function() {
    txb_param1.setValue(dts_ApplInfo.getCellData(dts_ApplInfo.getRowPosition(), "STD_CD_APPL_ID")); // 표준코드 신청 ID  
    txb_param2.setValue("2");
    fn_GetPar = fn_GetParam;
    ins_popupOpen("", "", "ULDINS91100", "첨부파일", "655", "350");
};


/********************************************** 
 * 함수명   : fn_Change_cfi
 * 설명       : cfi 변경 설정 - 채권과 동일 .....
 ***********************************************/
scwin.fn_Change_cfi = function() {
    // Cfi의 콤보 박스를 변경할 경우....
    var cfi = "";
    cfi = "D";
    if ($c.stf.getObjectValue(cmb_cb_p_group) == "") cfi += "_";

    else cfi += $c.stf.getObjectValue(cmb_cb_p_group);
    if ($c.stf.getObjectValue(cmb_cb_p_attr_1) == "") cfi += "_";

    else cfi += $c.stf.getObjectValue(cmb_cb_p_attr_1);
    if ($c.stf.getObjectValue(cmb_cb_p_attr_2) == "") cfi += "_";

    else cfi += $c.stf.getObjectValue(cmb_cb_p_attr_2);
    if ($c.stf.getObjectValue(cmb_cb_p_attr_3) == "") cfi += "_";

    else cfi += $c.stf.getObjectValue(cmb_cb_p_attr_3);
    if ($c.stf.getObjectValue(cmb_cb_p_attr_4) == "") cfi += "_";

    else cfi += $c.stf.getObjectValue(cmb_cb_p_attr_4);
    txb_CFI_CD.setValue(cfi); // cfi 설정

};


/********************************************** 
 * 함수명   : fn_set_Change
 * 설명       :  상세 조회시 CFI 상세 설정 
 ***********************************************/
scwin.fn_set_Change = function(str_cfi) {
    if (str_cfi == "") return;
    $c.stf.setObjectValue(cmb_cb_p_group, str_cfi.substring(1, 2));
    $c.stf.setObjectValue(cmb_cb_p_attr_1, str_cfi.substring(2, 3));
    $c.stf.setObjectValue(cmb_cb_p_attr_2, str_cfi.substring(3, 4));
    $c.stf.setObjectValue(cmb_cb_p_attr_3, str_cfi.substring(4, 5));
    $c.stf.setObjectValue(cmb_cb_p_attr_4, str_cfi.substring(5, 6));
};
scwin.gform_onload = function() {
    //cfi콤보셋팅
    ins_cfi_set(dts_cfi_group, scwin.vScrenID, SCREN_PROCS_TP_CD_01, "07", "D", "", "", "G");
    //hidden패널
    $c.stf.showObj(panel_12, false);
    scwin.fn_Init();
    var arrObjectApct = [txb_APCT_NM, txb_APCT_FAX_NO, txb_APCT_TEL_NO, txb_APCT_INNR_NO];
    for (var i = 0; i < arrObjectApct.length; i++) {
        fn_apct_delchar(arrObjectApct[i]);
    }
    txb_SRCH_STD_CD.focus();
};
scwin.dts_ApplInfo_OnLoadError = function() {
    $c.cm.CloseWin(-1, grd_ApplInfo);
    $c.stf.alert_error(dts_ApplInfo);

    // 조회버튼 활성.
    fn_SetDisableSelectBtn(btn_search, false);
};
scwin.dts_ApplInfo_OnLoadCompleted = function(rowcount) {
    if (dts_ApplInfo.errorMsg) {
        $c.win.alert(dts_ApplInfo.errorMsg);
    } else {
        txb_TotalCnt.setValue("총 " + rowcount + "건");
    }
    $c.cm.CloseWin(rowcount, grd_ApplInfo);

    // 조회버튼 활성.
    fn_SetDisableSelectBtn(btn_search, false);

    // 데이터가 없는 경우
    if (rowcount == 0) {
        fn_CtrlBtn_temp("no_data");
    } else {
        fn_CtrlBtn_temp("update");
        var CFI_CD = dts_ApplInfo.getCellData(dts_ApplInfo.getRowPosition(), "CFI_CD");
        scwin.fn_set_Change(CFI_CD);
    }
};
scwin.img_ISU_DD_onclick = function() {
    popUpCalendar2(edt_ISU_DD);
};
scwin.img_EXP_DD_onclick = function() {
    popUpCalendar2(edt_EXP_DD);
};
scwin.img_FROM_ISU_DD_onclick = function() {
    popUpCalendar2(edt_FROM_ISU_DD);
};
scwin.img_TO_ISU_DD_onclick = function() {
    popUpCalendar2(edt_TO_ISU_DD);
};
scwin.img_FROM_STD_CD_GRNT_DD_onclick = function() {
    popUpCalendar2(edt_FROM_STD_CD_GRNT_DD);
};
scwin.img_TO_STD_CD_GRNT_DD_onclick = function() {
    popUpCalendar2(edt_TO_STD_CD_GRNT_DD);
};
scwin.img_ISUR_CD_onclick = function() {
    ins_popupOpen(txb_ISUR_CD, txb_COM_NM, "ULDINS90400", "발행기관 코드", "460", "430");
};
scwin.img_SRCH_ISUR_CD_onclick = function() {
    ins_popupOpen(txb_SRCH_ISUR_CD, txb_SRCH_ISUR_NM, "ULDINS90400", "발행기관 코드", "460", "430");
};
scwin.img_ISUR_CD_INFO_onclick = function() {
    if ($c.stf.getObjectValue(txb_ISUR_CD) == "") {
        return;
    }
    txb_param1.setValue(txb_ISUR_CD.getValue()); // 발행기관 코드 
    txb_param2.setValue(txb_COM_NM.getValue()); // 발행기관명  
    fn_GetPar = fn_GetParam;
    ins_popupOpen("", "", "ULDINS91600", "발행기관 상세정보", "770", "835");
};
scwin.btn_search_onclick = function() {
    scwin.ins_Search();
};
scwin.btn_basisunm_onclick = function() {
    if ($c.stf.getObjectValue(txb_ISUR_CD) == "") {
        $c.win.alert("발행기관코드 입력하세요.");
        txb_ISUR_CD.focus();
        return;
    }
    txb_param1.setValue(txb_ISUR_CD.getValue()); // 발행기관 코드 
    txb_param2.setValue(txb_COM_NM.getValue()); // 발행기관명  
    fn_GetPar = fn_GetParam;
    ins_isuNmpopupOpen(txb_ISU_NM, txb_ISU_ABBRV, txb_ISU_ENG_NM, txb_ISU_ENG_ABBRV); // 종목기준명 호출 */

};
scwin.btn_modify_onclick = function() {
    // 사전체크
    if (!scwin.fn_ChkValid("save")) {
        return;
    }
    // 수정
    ins_popupOpen(txb_DEL_RSN, "", "ULDINS93900", "수정사유", "470", "190");
};
scwin.trs_Save_OnFail = function() {
    alert_tr_error(trs_Save);
};
scwin.trs_Save_OnSuccess = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0001"));

    // 재조회
    //ins_Search(); 

};
scwin.btn_delete_onclick = function() {
    // 삭제
    scwin.ins_Delete();
};
scwin.trs_Delete_OnFail = function() {
    alert_tr_error(trs_Delete);
};
scwin.trs_Delete_OnSuccess = function() {
    //alert( getMessageParam("MSG-A001", "삭제") );
    $c.win.alert($c.stf.getMessageParam("MSG-0001"));

    // 재조회
    scwin.ins_Search();
};
scwin.btn_prcnm_onclick = function() {
    txb_param1.setValue(txb_STD_CD.getValue()); // 표준코드 
    txb_param2.setValue("");
    fn_GetPar = fn_GetParam;
